import api from "./api";

const getRoles = () => api.get("/api/v1/roles/").then(r => r.data);
const getPermissionsGrouped = () => api.get("/api/v1/permissions/grouped").then(r => r.data);

const createRole = (payload) => api.post("/api/v1/roles/", payload).then(r => r.data);
const updateRole = (id, payload) => api.put(`/api/v1/roles/${id}`, payload).then(r => r.data);
const deleteRole = (id) => api.delete(`/api/v1/roles/${id}`);

const roleService = { getRoles, getPermissionsGrouped, createRole, updateRole, deleteRole };
export default roleService;
